    Bug 1948793 - Attempt to fix browser_feedBodyScroll.js. r=vineet

    From my observations, the test times out because the listener for the
    `scroll` event is registered after the `keypress` event has been issued.

    Since the `EventUtils` are also available inside a spawned `SpecialPowers`,
    this patch moves the call to `EventUtils.synthesizeKey()` inside and
    after the registration of the `scroll` event.

    Differential Revision: https://phabricator.services.mozilla.com/D239104

diff --git a/mail/base/test/browser/browser_feedBodyScroll.js b/mail/base/test/browser/browser_feedBodyScroll.js
index a79946535e2..f0363f7c894 100644
--- a/mail/base/test/browser/browser_feedBodyScroll.js
+++ b/mail/base/test/browser/browser_feedBodyScroll.js
@@ -76,7 +76,6 @@ add_task(async function test_feedBodyScroll() {
    * @returns {Promise<?ScrollState>}
    */
   async function checkScroll(value = 0) {
-    EventUtils.synthesizeKey(" ", {}, window);
     const scroll = await SpecialPowers.spawn(browser, [], async () => {
       const { promise, resolve } = Promise.withResolvers();
       content.addEventListener(
@@ -86,6 +85,7 @@ add_task(async function test_feedBodyScroll() {
         },
         { once: true }
       );
+      EventUtils.synthesizeKey(" ", {}, content);

       await promise;
